        title: this.lang === "zh" ? "输入工作目录路径" : "Enter workspace path",
        body: this.lang === "zh"
          ? "用于选择器范围外的服务器目录；请输入已存在目录的绝对路径。"
          : "For server folders outside the browser roots, enter an existing absolute path.",
        placeholder: "/path/to/project",
